using GameSaves.Core.Catalog;
using GameSaves.External.Http;

namespace GameSaves.External
{
    public sealed class PcgwHarvestOptions
    {
        public required string DatabasePath { get; init; }

        public required string OutputRoot { get; init; }

        public required string UserAgent { get; init; }

        public IReadOnlyList<string> SteamAppIds { get; init; } = Array.Empty<string>();

        /// <summary>
        /// Optional path to a tracklist file (e.g. missing-titles.json or missing-titles.csv generated by OBS-015).
        /// </summary>
        public string? TracklistPath { get; init; }

        /// <summary>
        /// Optional pre-loaded tracklist instance.
        /// </summary>
        public MissingTitlesTracklist? Tracklist { get; init; }

        /// <summary>
        /// When true, skips harvesting any AppID that already has mappings in the save path database.
        /// </summary>
        public bool SkipExistingInDatabase { get; init; } = false;

        public int RequestsPerMinute { get; init; } = 20;

        public int PauseEveryRequests { get; init; } = 20;

        public TimeSpan PauseEveryRequestsDuration { get; init; } = TimeSpan.FromMinutes(1);

        public int MaxTitlesToProcess { get; init; } = 0;

        public bool ImportExtractedMappingsDisabled { get; init; } = true;

        public RateLimitOptions ToRateLimitOptions()
        {
            return new RateLimitOptions
            {
                RequestsPerMinute = RequestsPerMinute,
                PauseEveryRequests = PauseEveryRequests,
                PauseEveryRequestsDuration = PauseEveryRequestsDuration
            };
        }
    }
}